SELECT 
FROM FILE_FOLDER FF
WHERE FF.FOLDER_ID = #{folderId}

SELECT 
FROM FILE_FOLDER FF

    FF.PARENT_ID IS NULL
    AND FF.SCOPE = #{scope}
    AND FF.DEPTNO = #{deptno}

ORDER BY FF.FOLDER_NAME ASC

SELECT 
FROM FILE_FOLDER FF

    FF.PARENT_ID = #{parentId}
    AND FF.SCOPE = #{scope}
    AND FF.DEPTNO = #{deptno}

ORDER BY FF.FOLDER_NAME ASC

